using System.Text.RegularExpressions;

/// <summary>
/// Static class to hold const variables to be used in AVA model
/// </summary>
internal final class AVARUMConstants
{
    public const str emptyString                        = '';
    public const str space                              = ' ';                            
    public const str pipeSeparator                      = '|';
    public const str fieldDelimiter                     = '\,';
    public const str recordDelimiter                    = '\n';
    public const str semiColan                          = ';';
    public const str comma                              = ',';  
    public const str emailSeperator                     = ';';     
    public const str dot                                = '.';
    public const str underscore                         = '_';
    public const str fileDelimiter                      = '\r\n';
    public const str asterisk                           = '*';    

    public const str excelFileFormat                    = '.xlsx';
    public const str csvFileFormat                      = '.csv';       
    public const str pdfFileFormat                      = '.pdf';

    public const str jsonContentType                    = 'application/json';
    public const str jsonDelimeter                      = ':';

    public static str createDateTime                    = strUpr(identifierStr(CreatedDateTime));

    public const str keepNummericPattern                = '0123456789';       
    public static Regex lineBreakRegEx                  = new Regex(@'[\r|\n]+', RegexOptions::IgnoreCase);
    public static Regex whiteSpaceRegEx                 = new Regex(@'\s+', RegexOptions::IgnoreCase);
}
